import{_ as a,o as t,c as n,a5 as r}from"./chunks/framework.bIR-4glx.js";const m=JSON.parse('{"title":"Last Year and Now","description":"A complete English translation of a 2016 post about graduation, returning home, a first website, and early companies.","frontmatter":{"title":"Last Year and Now","description":"A complete English translation of a 2016 post about graduation, returning home, a first website, and early companies.","updated":"2026-09-01T00:00:00.000Z"},"headers":[],"relativePath":"en/threads/archive/last-year-and-now.md","filePath":"en/threads/archive/last-year-and-now.md","lastUpdated":1788220800000}'),o={name:"en/threads/archive/last-year-and-now.md"};function i(s,e,d,c,h,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="last-year-and-now" tabindex="-1">Last Year and Now <a class="header-anchor" href="#last-year-and-now" aria-label="Permalink to &quot;Last Year and Now&quot;">​</a></h1><p><strong>Editor&#39;s note (2026-08-31):</strong> The self-introduction, projects, companies, income, and health details belong to a 2016 snapshot. They do not describe the author&#39;s current status or constitute business, investment, or career advice. Read this as retrospective material, not a route to copy.</p><blockquote><p>Original date: 2016-04-24. The original Wayback Machine snapshot now returns 404; this page preserves the repository&#39;s historical text and does not treat the dead address as reviewable evidence.</p></blockquote><p>The previous year I was a university senior. On 7 March 2015 I went to Beijing, originally to find an internship. Successful interviews gave me confidence and made me more ambitious, so I spent much of two months interviewing.</p><p>Just as I prepared to join an automotive website, the university ordered me back. I had missed the mid-term defence, and missing the final defence would mean no graduation certificate.</p><p>I had retaken thirteen courses in the first semester precisely so that I could graduate, so I returned. During the defence I admitted that I had bought my circuit board online and was sent to a second defence. With a teacher&#39;s guidance I rebuilt it, completed most required functions, and passed after handling the presentation reasonably well.</p><p>I still did not receive the certificate on time because I had missed two third-year internships and needed to complete them with the next class. I returned to my hometown.</p><p>Many things happened there. Two stand out: I learned to cook, and I developed arthritis.</p><p>At the beginning of 2016 I decided to stop drifting and began building a film website. After a period of work, <code>bt0.com</code> gained its first users and encouraging feedback.</p><p>I then accepted several web-design projects, earned some spending money, and began an entrepreneurial journey with a former classmate. We had our first company in March, established another internet company in Shenyang in April, and began applying for a third in Nanjing under a name I had long liked.</p><p>We developed quickly over a short period, though we believed it came from preparation. I thanked several friends and my younger brother.</p><p>At the time, I described myself as owning two small internet companies serving cryptocurrency and games. It was my zodiac year, and I wrote that I wanted to work steadily, avoid rushing, and boast less.</p><h2 id="original-comment" tabindex="-1">Original Comment <a class="header-anchor" href="#original-comment" aria-label="Permalink to &quot;Original Comment&quot;">​</a></h2><p>A reader praised <code>bt0</code>. The comment is preserved as part of the historical snapshot, not as a current product endorsement.</p>',14)])])}const u=a(o,[["render",i]]);export{m as __pageData,u as default};
